package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user name's role on a sheet: clerk, steward or viewer. A name with none is a clerk. */
@Entity
@Table(name = "sheet_role")
public class Role {

    public static final String CLERK = "clerk";

    public static final String STEWARD = "steward";

    /** Sees every screen and figure and can change nothing. */
    public static final String VIEWER = "viewer";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(nullable = false)
    private String role;

    protected Role() {
    }

    public Role(String sheetId, String userName, String role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}
package net.officefloor.hq.app.role;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the role form from the body; refuses a blank user name and a role other than clerk, steward or viewer. */
public class ValidateRole {

    private static final Set<String> ROLES = Set.of(Role.CLERK, Role.STEWARD, Role.VIEWER);

    public void validate(@RequestBody RoleRequest request, Out<RoleInput> body) throws InvalidRoleException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        String role = request == null || request.role() == null ? "" : request.role().trim();
        if (user.isEmpty()) {
            throw new InvalidRoleException("The user name must not be blank.");
        }
        if (!ROLES.contains(role)) {
            throw new InvalidRoleException("The role must be clerk, steward or viewer.");
        }
        body.set(new RoleInput(user, role));
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface RoleRepository extends JpaRepository<Role, Long> {

    List<Role> findBySheetIdOrderByUserNameAsc(String sheetId);

    Optional<Role> findBySheetIdAndUserName(String sheetId, String userName);

    /** The role the user name acts in on the sheet: steward while the sheet's today is inside a delegation to it,
     *  else its own role. */
    default String roleOf(String sheetId, String userName) {
        String own = ownRoleOf(sheetId, userName);
        return !Role.STEWARD.equals(own) && delegatorOf(sheetId, userName) != null ? Role.STEWARD : own;
    }

    /** The user name's own role on the sheet, leaving delegations aside: clerk unless one is set. */
    default String ownRoleOf(String sheetId, String userName) {
        return findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** The steward the user name acts for on the sheet's today (the latest delegation to it covering that day), or
     *  null when none. */
    default String delegatorOf(String sheetId, String userName) {
        List<String> by = activeDelegators(sheetId, userName);
        return by.isEmpty() ? null : by.get(0);
    }

    @Query("select d.byName from Delegation d, Sheet s where s.id = :sheetId and d.sheetId = :sheetId"
            + " and d.userName = :userName and d.fromDate <= s.today and d.toDate >= s.today order by d.id desc")
    List<String> activeDelegators(@Param("sheetId") String sheetId, @Param("userName") String userName);
}
package net.officefloor.hq.app.role;

import net.officefloor.hq.app.AuditUser;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** The first step of every change: refuses it, before anything is read or written, when the signed-in name is a
 *  viewer on the sheet (a viewer sees everything and changes nothing). */
public class GuardViewer {
    public void guard(@PathVariable("sheetId") String sheetId,
            @RequestHeader(name = "X-User", required = false) String user, RoleRepository roles)
            throws ViewerRefusedException {
        if (Role.VIEWER.equals(roles.roleOf(sheetId, AuditUser.decode(user)))) {
            throw new ViewerRefusedException("A viewer cannot change anything on the sheet.");
        }
    }
}
