import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A user name's role on the sheet: clerk, steward or viewer. A name with none is a clerk. */
export type Role = { user: string; role: string };

/** The sheet's settings: its clerk limit with two decimals (null when there is none) and its floor with two
 *  decimals (a claim's live due is at least it), and its terms in days (a claim is due by its date plus them), and its late percent with two decimals (an overdue claim's due gains,
 *  for each full 30 days overdue, the one in force on that boundary date of its figure), and its policy date (YYYY-MM-DD; "" when blank: the sheet's today — a claim
 *  dated before it rounds half up, one on or after it half to even), and its period numbering from (YYYY-MM-DD; "" when off — while the sheet's today is
 *  on or after it, a claim opened is numbered within its period), and the own terms in days of grades A, B and C ("" when the
 *  grade uses the sheet's terms; a claim's due-by is fixed when it is created, from its person's grade on its date), and its cap with
 *  two decimals ("" when there is none — a person's due-total is at most it), and its proof threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof), and its grace days ("" when off; not dated), and its note threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be opened with an empty note), and its entry date (YYYY-MM-DD; "" when off; not dated — while it is set, a new claim left without a date is dated it in place of the sheet's today), and the grace days of grades A, B and C ("" when none — an overdue claim's lateness counts from its due-by plus those of its person's grade on its date, in force on its date), and the proof thresholds of grades A, B and C with two decimals ("" when none — a claim of its person's grade on its date uses the one in force then in place of the sheet's), and its pot with two decimals ("" when there is none; not dated — shared out among the members of each balanced pool by their shares), and its parent sheet's id ("" when none; not dated — a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up), and its fiscal year start month (1 to 12; "1" unless set; not dated — a fiscal year starts on its first day in that month and is named FY<yyyy> by the calendar year that day falls in), and its alert threshold with two decimals ("" when off; not dated — a person whose due-total goes above it is alerted in the audit), and its rounding mode (half-up or half-even; "" when none — a claim with one in force on the date it rounds by rounds by it, else by the policy date), and its review threshold with two decimals ("" when there is none — a claim whose due is above the one in force on its date goes to REVIEW when opened), and its escalation gap in days ("" when off; not dated — reminding a claim whose previous reminder was at least that many days before the sheet's today escalates it, once per claim), and its review SLA in days ("" when none; not dated — a REVIEW claim whose review day plus that many days is before the sheet's today is late), and its proof kinds (comma separated; "" when none; not dated — while set, a claim whose due is above its proof threshold needs a proof of each to be settled or approved), and the clerk limits of grades A, B and C with two decimals ("" when none — a claim of its person's grade on the sheet's today uses the one in force then in place of the sheet's), and its default grade (A, B or C; "" when blank, meaning A; not dated — a person added by the quick-add bar, or by an import line with a blank grade, gets it). Each of those is the value in force on the
 *  sheet's today; `dated` holds the values recorded for each setting that carries a figure, by key (floor, late-pct,
 *  terms, terms-A/B/C, clerk-limit, clerk-limit-A/B/C, cap, proof-threshold, note-threshold, grace-A/B/C, proof-threshold-A/B/C, rounding, review-threshold), each from its from-date on (null: from the beginning of time; a null value is blank). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string;
  latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string; proofThreshold: string;
  dated: Record<string, { from: string | null; value: string | null }[]>;
  permOpen: string; permSettle: string; permVoid: string; permReassign: string; permClose: string; permReopen: string;
  graceDays: string; noteThreshold: string; entryDate: string;
  graceA: string; graceB: string; graceC: string;
  proofThresholdA: string; proofThresholdB: string; proofThresholdC: string; pot: string; parent: string;
  fiscalStartMonth: string; alertThreshold: string; rounding: string; reviewThreshold: string;
  escalateAfter: string; reviewSla: string; proofKinds: string; defaultGrade: string;
  clerkLimitA: string; clerkLimitB: string; clerkLimitC: string };

/** The value of a dated setting in force on a date (YYYY-MM-DD): the one recorded with the latest from-date on or
 *  before it, else `start` (the sheet's starting value). */
export function settingOn(settings: Settings | undefined, key: string, date: string, start: string): string {
  let found: { from: string | null; value: string | null } | undefined;
  for (const d of settings?.dated?.[key] ?? []) {
    if (d.from !== null && d.from > date) continue;
    if (!found || (found.from ?? '') <= (d.from ?? '')) found = d;
  }
  return found ? (found.value ?? start) : start;
}

/** The terms a sheet starts at, in days. */
export const DEFAULT_TERMS = '14';

export const rolesQueryKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;
export const rolesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/roles`;

export const settingsQueryKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const settingsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/settings`;

/** The user names given a role on the sheet, by name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Role[]>(rolesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(settingsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The steward role delegated by a steward (`by`) to a user name, from `from` to `to` (YYYY-MM-DD), inclusive, by
 *  the sheet's today: while today is inside it the user acts as a steward in every rule. */
export type Delegation = { user: string; by: string; from: string; to: string };

export const delegationsQueryKey = (sheetId: string) => ['sheet', sheetId, 'delegations'] as const;
export const delegationsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/delegations`;

/** The delegations made on the sheet, oldest first. */
export function useDelegations() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: delegationsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Delegation[]>(delegationsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { rolesPath, rolesQueryKey, useRoles, type Role } from './roles';

// The sheet's roles: each user name given one, and the form that gives a name a role — clerk (what any
// name is by default), steward, or viewer (sees everything, changes nothing — the server refuses each change).
function Roles() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const roles = useRoles();
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { user: string; role: string }) => putJson<Role>(rolesPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesQueryKey(sheet ?? '') });
      setName('');
      setRole('');
    },
  });
  const submit = useSubmitOnce(save);

  if (!user || !sheet) return null;
  return (
    <section data-testid="roles">
      <h2>Roles</h2>
      <table>
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="role-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ user: name, role });
        }}
      >
        <input
          data-testid="role-form-user"
          placeholder="User name"
          value={name}
          onChange={(e) => { setName(e.target.value); save.reset(); }}
        />
        <input
          data-testid="role-form-role"
          placeholder="Role (clerk, steward or viewer)"
          value={role}
          onChange={(e) => { setRole(e.target.value); save.reset(); }}

